@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + buildingID : int
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + email : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + content : string
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
WebPortal "1" -- "*" Comment
Building "1" -- "*" AdditionalEntry
Building "1" -- "*" Image
Building "1" -- "0..1" Image : profile photo
User "1" -- "*" Building : owner
User "1" -- "*" Comment : author
Comment "*" -- "1" Building : target

@enduml

